  miA5tree = std::pow(za(j1,j3),3)*za(j2,j3)/(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j5)*za(j5,j1));

  Vggluon = -five*epinv*epinv2
    - epinv*(lnrat(musq,-s(j1,j2))+lnrat(musq,-s(j2,j3))+lnrat(musq,-s(j3,j4))
            +lnrat(musq,-s(j4,j5))+lnrat(musq,-s(j5,j1)))
    - half*(std::pow(lnrat(musq,-s(j1,j2)),2)+std::pow(lnrat(musq,-s(j2,j3)),2)+std::pow(lnrat(musq,-s(j3,j4)),2)
            +std::pow(lnrat(musq,-s(j4,j5)),2)+std::pow(lnrat(musq,-s(j5,j1)),2))
    + lnrat(-s(j1,j2),-s(j2,j3))*lnrat(-s(j3,j4),-s(j4,j5))
    + lnrat(-s(j2,j3),-s(j3,j4))*lnrat(-s(j4,j5),-s(j5,j1))
    + lnrat(-s(j3,j4),-s(j4,j5))*lnrat(-s(j5,j1),-s(j1,j2))
    + lnrat(-s(j4,j5),-s(j5,j1))*lnrat(-s(j1,j2),-s(j2,j3))
    + lnrat(-s(j5,j1),-s(j1,j2))*lnrat(-s(j2,j3),-s(j3,j4))
    + five/six*pisq;
  Vg12 = Vggluon+epinv*epinv2+epinv*lnrat(musq,-s(j1,j2))+half*std::pow(lnrat(musq,-s(j1,j2)),2);

  VSUSY = Vggluon-3.0*epinv-1.5*(lnrat(musq,-s(j3,j4))+lnrat(musq,-s(j5,j1)))-6.0;
  VL = Vg12-1.5*(epinv+lnrat(musq,-s(j3,j4)))+lnrat(-s(j5,j1),-s(j1,j2))-3.0;

  // Eq. (5.14)
  FSUSY =
    - 3.0*za(j1,j3)*za(j2,j3)*za(j4,j1)*std::pow(zb(j2,j4),2)/(za(j4,j5)*za(j5,j1))
      *Ls1(-s(j2,j3),-s(j5,j1),-s(j3,j4),-s(j5,j1))/std::pow(s(j5,j1),2)
    + 3.0*za(j1,j3)*za(j2,j3)*za(j5,j3)*std::pow(zb(j2,j5),2)/(za(j3,j4)*za(j4,j5))
      *Ls1(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4))/std::pow(s(j3,j4),2)
    - 1.5*std::pow(za(j1,j3),2)/(za(j1,j2)*za(j3,j4)*za(j4,j5)*za(j5,j1))
      *(za(j1,j5)*zb(j5,j2)*za(j2,j3)+za(j1,j2)*zb(j2,j4)*za(j4,j3))
      *L0(-s(j3,j4),-s(j5,j1))/s(j5,j1);

  Ffgluon = FSUSY*za(j3,j1)/(3.0*za(j3,j2));

  FS = one/three *
    ( za(j1,j5)*zb(j2,j5)*za(j3,j4)*za(j3,j5)*std::pow(zb(j4,j5),2)/za(j4,j5)
      *2.0*L2(-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),3)
    - za(j1,j3)*za(j1,j5)*za(j3,j4)*std::pow(zb(j4,j5),2)/(za(j1,j2)*za(j4,j5))
      *L1(-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),2)
    - za(j1,j3)*zb(j2,j4)*zb(j4,j5)/(za(j1,j2)*zb(j1,j2)*zb(j3,j4)*za(j4,j5))
    + std::pow(zb(j2,j4),2)*zb(j2,j5)/(zb(j1,j2)*zb(j2,j3)*zb(j3,j4)*za(j4,j5)) );

  FL = FS
    - za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*std::pow(zb(j2,j4),3)/(za(j4,j5)*za(j5,j1))
      *Ls2(-s(j2,j3),-s(j5,j1),-s(j3,j4),-s(j5,j1))/std::pow(s(j5,j1),3)
    - za(j1,j2)*za(j2,j3)*std::pow(za(j3,j5),2)*std::pow(zb(j2,j5),3)/(za(j3,j4)*za(j4,j5))
      *Ls2(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4))/std::pow(s(j3,j4),3)
    - 2.0*za(j1,j3)*za(j2,j3)*za(j4,j1)*std::pow(zb(j2,j4),2)/(za(j4,j5)*za(j5,j1))
      *Ls1(-s(j2,j3),-s(j5,j1),-s(j3,j4),-s(j5,j1))/std::pow(s(j5,j1),2)
    - 2.0*za(j1,j3)*za(j2,j3)*za(j3,j5)*std::pow(zb(j2,j5),2)/(za(j3,j4)*za(j4,j5))
      *Ls1(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4))/std::pow(s(j3,j4),2)
    - std::pow(za(j1,j3),2)*zb(j2,j4)/(za(j4,j5)*za(j5,j1))
      *Ls0(-s(j2,j3),-s(j5,j1),-s(j3,j4),-s(j5,j1))/s(j5,j1)
    - std::pow(za(j1,j3),2)*za(j3,j5)*zb(j2,j5)/(za(j3,j4)*za(j4,j5)*za(j5,j1))
      *Ls0(-s(j1,j2),-s(j3,j4),-s(j5,j1),-s(j3,j4))/s(j3,j4)
    - ( za(j1,j3)*std::pow(za(j2,j3),2)*std::pow(zb(j2,j5),2)*za(j1,j5)/(za(j1,j2)*za(j3,j4)*za(j4,j5))
        + 0.5*std::pow(za(j1,j3),2)*zb(j1,j2)*za(j2,j3)*zb(j2,j5)/(za(j3,j4)*za(j4,j5)) )
      *L1(-s(j3,j4),-s(j5,j1))/std::pow(s(j5,j1),2)
    + 0.5*za(j1,j3)*za(j1,j4)*za(j2,j3)*std::pow(zb(j2,j4),2)/(za(j4,j5)*za(j5,j1))
      *L1(-s(j2,j3),-s(j5,j1))/std::pow(s(j5,j1),2)
    - 0.5*za(j1,j3)*za(j1,j5)*za(j3,j4)*std::pow(zb(j4,j5),2)/(za(j1,j2)*za(j4,j5))
      *L1(-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),2)
    + 0.5*std::pow(za(j1,j3),2)*zb(j2,j4)/(za(j4,j5)*za(j5,j1))
      *L0(-s(j3,j4),-s(j5,j1))/s(j5,j1)
    - ( 2.0*std::pow(za(j1,j3),2)*zb(j4,j5)/(za(j1,j2)*za(j4,j5))
        + std::pow(za(j1,j3),2)*za(j3,j5)*zb(j2,j5)/(za(j3,j4)*za(j4,j5)*za(j5,j1)) )
      *L0(-s(j1,j2),-s(j3,j4))/s(j3,j4)
    + 0.5*za(j1,j4)*std::pow(zb(j2,j4),2)*zb(j4,j5)/(za(j4,j5)*zb(j2,j3)*zb(j3,j4)*s(j5,j1))
    - za(j1,j3)*za(j2,j3)*zb(j2,j5)*zb(j4,j5)/(za(j1,j2)*za(j3,j4)*zb(j3,j4)*za(j4,j5)*zb(j1,j5))
    - 0.5*std::pow(za(j1,j3),2)*zb(j1,j2)*za(j2,j3)*zb(j2,j5)
      /(std::pow(za(j3,j4),2)*zb(j3,j4)*za(j4,j5)*za(j1,j5)*zb(j1,j5));

  Ff = -std::pow(za(j1,j3),2)*zb(j4,j5)/(za(j1,j2)*za(j4,j5))
    *L0(-s(j1,j2),-s(j3,j4))/s(j3,j4);

  AL = VL*miA5tree+FL; // @coverage-probe
  ASUSY = VSUSY*miA5tree+FSUSY;
  // Vs = Vf =0, per Eq. (5.10)
  Af = Ff;
  As = FS;

  return;
}

