  void A5qbmqpgmgpgp_wrapper(int j1, int j2, int j3, int j4, int j5, std::complex<double>* fza, std::complex<double>* fzb, std::complex<double>& miA5tree, std::complex<double>& AL, std::complex<double>& ASUSY, std::complex<double>& Af, std::complex<double>& As) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    A5qbmqpgmgpgp(j1, j2, j3, j4, j5, za, zb, miA5tree, AL, ASUSY, Af, As);
  }
